// Solo dejamos pasar los adjuntos PDF (el resto se ignora)
const salida = [];
for (const item of $input.all()) {
  const binarios = item.binary || {};
  for (const [clave, archivo] of Object.entries(binarios)) {
    if (archivo.mimeType === 'application/pdf' || (archivo.fileName || '').toLowerCase().endsWith('.pdf')) {
      salida.push({ json: { remitente: item.json.from, archivo: archivo.fileName }, binary: { data: archivo } });
    }
  }
}
return salida;

// Interpreta el texto de la factura con expresiones regulares (misma idea que src/parser.ts)
// Lamia Derouach
const num = (t) => { if (!t) return 0; t = t.replace(/[€\s]/g, ''); if (t.includes(',')) t = t.replace(/\./g, '').replace(',', '.'); return parseFloat(t) || 0; };
const redondear = (n) => Math.round(n * 100) / 100;
const fecha = (t) => { const m = (t || '').match(/(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})/); return m ? m[3] + '-' + m[2].padStart(2, '0') + '-' + m[1].padStart(2, '0') : ''; };
const salida = [];
for (const item of $input.all()) {
  const texto = item.json.text;
  const lineas = texto.split('\n').map((l) => l.trim()).filter(Boolean);
  const buscar = (re) => { for (const l of lineas) { const m = l.match(re); if (m) return m[1]; } return ''; };

  // Líneas de detalle: concepto cantidad precio [dto%] importe [IVA%]
  const detalle = [];
  for (const l of lineas) {
    const m = l.match(/^(.+?)\s+(\d+(?:[.,]\d+)?)\s+([\d.,]+)\s*€?\s+(?:(\d+(?:[.,]\d+)?)\s*%\s+)?([\d.,]+)\s*€?(?:\s+(\d+(?:[.,]\d+)?)\s*%)?$/);
    if (m && !/total|base|iva/i.test(m[1])) detalle.push({ concepto: m[1], cantidad: num(m[2]), precioUnitario: num(m[3]), descuento: num(m[4]), importe: num(m[5]), tipoIva: m[6] !== undefined ? num(m[6]) : -1 });
  }

  // Impuestos: cada tipo de IVA por separado (no se supone siempre el 21 %)
  const bases = {};
  for (const l of lineas) {
    const m = l.match(/^base\s*imponible\s*\(?\s*(\d+(?:[.,]\d+)?)\s*%\s*\)?\s*:?\s*([\d.,]+)/i);
    if (m) bases[num(m[1])] = num(m[2]);
  }
  const desglose = [];
  for (const l of lineas) {
    const m = l.match(/^(?:iva|igic|impuestos?)\s*\(?\s*(\d+(?:[.,]\d+)?)\s*%\s*\)?\s*(?:sobre\s*([\d.,]+)\s*€?)?\s*:?\s*([\d.,]+)\s*€?$/i);
    if (!m) continue;
    const tipo = num(m[1]);
    const cuota = num(m[3]);
    const base = bases[tipo] !== undefined ? bases[tipo] : (m[2] ? num(m[2]) : (tipo > 0 ? redondear(cuota * 100 / tipo) : 0));
    const ya = desglose.find((d) => d.tipo === tipo);
    if (ya) { ya.base = redondear(ya.base + base); ya.cuota = redondear(ya.cuota + cuota); } else desglose.push({ tipo, base, cuota });
  }
  desglose.sort((a, b) => b.tipo - a.tipo);

  let baseImponible = num(buscar(/^base\s*imponible\s*:?\s*([\d.,]+)\s*€?$/i));
  let impuestos = desglose.length ? redondear(desglose.reduce((s, d) => s + d.cuota, 0)) : num(buscar(/IVA\s*\(?[\d.,]*%?\)?\s*:?\s*([\d.,]+)\s*€/i));
  if (!baseImponible && desglose.length) baseImponible = redondear(desglose.reduce((s, d) => s + d.base, 0));
  if (!baseImponible && detalle.length) baseImponible = redondear(detalle.reduce((s, l) => s + l.importe, 0));
  // Con un solo tipo de IVA, la base es la base imponible de la factura
  if (desglose.length === 1 && baseImponible > 0) desglose[0].base = baseImponible;
  // Si no había desglose pero sí base e impuestos, se deduce el tipo (al medio punto más cercano)
  if (!desglose.length && (baseImponible > 0 || impuestos > 0)) {
    desglose.push({ tipo: baseImponible > 0 ? Math.round(impuestos / baseImponible * 200) / 2 : 0, base: baseImponible, cuota: impuestos });
  }
  // Las líneas sin IVA propio usan el tipo con más base
  const porDefecto = desglose.length ? [...desglose].sort((a, b) => b.base - a.base)[0].tipo : 21;
  for (const l of detalle) if (l.tipoIva < 0) l.tipoIva = porDefecto;

  salida.push({ json: {
    numero: buscar(/n[ºo°]\s*factura\s*[:.]?\s*(\S+)/i),
    proveedor: buscar(/^emisor\s*[:.]\s*(.+)$/i),
    proveedorNif: buscar(/NIF\s*[:.]?\s*(\w+)/i),
    cliente: buscar(/^cliente\s*[:.]\s*(.+)$/i),
    clienteNif: '',
    fechaEmision: fecha(buscar(/emisi[oó]n\s*[:.]?\s*(\S+)/i)),
    fechaVencimiento: fecha(buscar(/vencimiento\s*[:.]?\s*(\S+)/i)),
    baseImponible,
    impuestos,
    total: num(buscar(/^total\s*:?\s*([\d.,]+)/i)),
    estado: 'pendiente',
    archivo: $('2. Filtrar solo PDF').item.json.archivo,
    remitente: $('2. Filtrar solo PDF').item.json.remitente,
    fechaRecepcion: new Date().toISOString().slice(0, 10),
    lineas: detalle,
    desglose
  }});
}
return salida;
